import sys

def main():
    import sys
    import bisect
    l = sys.stdin.readline().strip()
    r = sys.stdin.readline().strip()
    n = int(sys.stdin.readline().strip())

    def count_modest_substrings(s):
        count = 0
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                if s[i] != '0':
                    num = int(s[i:j])
                    if int(l) <= num <= int(r):
                        count += 1
        return count

    def is_valid(s):
        for i in range(len(s)):
            for j in range(i +1, len(s) + 1):
                if s[i] !='0':
                    num = int(s[i:j])
                    if not (int(l) <= num <= int(r)):
                        return False
        return True

    def find_best_string(n):
        best_string = '0' * n
        best_count = 0
        queue = ['1']
        while queue:
            current = queue.pop(0)
            if len(current) > n:
                continue
            count = count_modest_substrings(current)
            if count > best_count or (count == best_count and current < best_string):
                best_count = count
                best_string = current
            if len(current) < n:
                for digit in '0123456789':
                    new_string = current + digit
                    if is_valid(new_string):
                        queue.append(new_string)
        return best_string[:n], best_count

    result_string, result_count = find_best_string(n)
    print(result_count)
    print(result_string)

